INSERT INTO public.erp_ajuda_campo (chave, rota, grupo, vertical, ordem, rotulo, o_que_preencher, para_que_serve, exemplo, erro_comum)
VALUES
  ('projetos.insumos.form.codigo', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 1, 'Código', 'O código do material na sua empresa. É obrigatório; use o mesmo do seu estoque ou da nota do fornecedor, se houver.', 'Identifica o insumo na composição dos serviços e nas importações de planilha. Não entra no cálculo do preço.', 'INS-0012', 'Usar o mesmo código para dois materiais diferentes — a composição pega o errado.'),
  ('projetos.insumos.form.unidade', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 2, 'Unidade', 'Como o material é comprado e consumido: un, m, m², kg, saco etc. É obrigatória.', 'O custo atual é por esta unidade, e a quantidade do insumo em cada serviço também. Unidade errada distorce o custo do serviço inteiro.', 'sc (saco de 40 kg de massa)', 'Cadastrar em kg e lançar no serviço a quantidade em sacos.'),
  ('projetos.insumos.form.nome', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 3, 'Nome', 'O nome do material como a obra conhece, com a medida quando ajudar a distinguir.', 'É por ele que você acha o insumo ao montar a composição de um serviço e que ele aparece no orçamento.', 'Placa de gesso ST 1,20 × 1,80 m', 'Nome genérico ("Placa") — vira uma lista de itens iguais na busca.'),
  ('projetos.insumos.form.categoria', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 4, 'Categoria', 'Opcional. O grupo do material, para filtrar a lista.', 'Organiza a lista de insumos e os relatórios de consumo por tipo de material. Não muda o preço.', 'Gesso e drywall', 'Criar categorias parecidas ("Gesso" e "Gessos") — o filtro se divide.'),
  ('projetos.insumos.form.custo', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 5, 'Custo atual (R$)', 'Quanto você paga hoje por UMA unidade do material, com frete se ele vier embutido.', 'É o custo do material em todos os serviços que usam este insumo: quantidade × custo atual. Atualizar aqui atualiza o custo dos serviços.', 'R$ 38,90 por placa', 'Lançar o preço da caixa/fardo numa unidade de "un" — o custo do serviço explode.'),
  ('projetos.insumos.form.fornecedor', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 6, 'Fornecedor', 'Opcional. De quem você costuma comprar este material.', 'Ajuda a cotar de novo e a conferir variação de preço. Não entra no cálculo.', 'Distribuidora Gesso Sul', 'Escrever o nome cada vez de um jeito — dificulta achar o fornecedor depois.'),
  ('projetos.insumos.form.ncm', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 7, 'NCM', 'Opcional. O código fiscal de 8 dígitos do produto (vem na nota do fornecedor).', 'Usado quando o material vai para nota fiscal ou para o cálculo de impostos de revenda. Não muda o custo na composição.', '68091100', 'Digitar com pontos ou com menos de 8 dígitos.'),
  ('projetos.insumos.form.especificacao', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 8, 'Especificação técnica', 'Opcional. Características que importam na compra: norma, espessura, cor, resistência.', 'Garante que a compra traga o material certo e serve de referência na proposta.', 'Placa standard, 12,5 mm, borda rebaixada, NBR 14715', 'Colocar aqui o preço ou o fornecedor — eles têm campo próprio.'),
  ('projetos.insumos.form.observacoes', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 9, 'Observações', 'Opcional. Qualquer nota interna sobre o material.', 'Fica só para consulta da equipe. Não entra no cálculo nem na proposta.', 'Comprar em lote de 50 para ter desconto', 'Guardar informação que deveria estar em outro campo (custo, unidade).'),
  ('projetos.insumos.form.status', '/dashboard/projetos/insumos', 'Insumo', 'hub_projetos', 10, 'Status', 'Ativo para usar em serviços novos; Inativo para tirar da escolha sem apagar.', 'Inativo some da busca ao montar composições, mas continua nos serviços e orçamentos que já o usam.', 'Inativo quando o material saiu de linha', 'Inativar achando que muda os serviços antigos — eles continuam com o item.'),
  ('projetos.mao_obra.legado.busca', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 1, 'Buscar', 'Digite parte da função, do código ou da descrição.', 'Só filtra a lista na tela. Não muda nenhum valor.', 'gess', 'Esquecer um filtro de Tipo/Status ligado e achar que a função sumiu.'),
  ('projetos.mao_obra.legado.filtro_tipo', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 2, 'Tipo', 'Escolha um tipo de contratação para ver só essas funções, ou Todos.', 'Só filtra a lista. Não muda o custo.', 'PJ', 'Deixar filtrado e não encontrar uma função CLT.'),
  ('projetos.mao_obra.legado.filtro_status', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 3, 'Status', 'Ativos, Inativos ou Todos.', 'Só filtra a lista. Inativas não aparecem para novos serviços.', 'Inativos, para reativar uma função antiga', 'Procurar uma função inativa com o filtro em Ativos.'),
  ('projetos.mao_obra.legado.filtro_origem', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 4, 'Origem', 'Manual (você criou) ou Biblioteca (veio do catálogo público), ou Todas.', 'Só filtra a lista. Ajuda a revisar o que foi importado.', 'Biblioteca, para revisar o que importou', 'Achar que Biblioteca é outra empresa — são cópias suas, editáveis.'),
  ('projetos.mao_obra.legado.codigo', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 5, 'Código', 'Opcional. Um código curto da função.', 'Organiza a lista e as importações. Não entra no cálculo.', 'MO-GES', 'Repetir o código de outra função.'),
  ('projetos.mao_obra.legado.tipo', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 6, 'Tipo', 'Como o profissional é contratado: CLT, PJ, Terceirizado ou Empreitada.', 'Define que encargos fazem sentido: CLT costuma ter encargos altos; PJ e empreitada, quase nenhum.', 'CLT', 'Marcar PJ e manter 80% de encargos — o custo fica inflado.'),
  ('projetos.mao_obra.legado.funcao', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 7, 'Função', 'O nome da função na obra. É obrigatório.', 'É a mão de obra que você escolhe na composição do serviço; o custo/hora dela entra no custo do serviço.', 'Gesseiro', 'Cadastrar a mesma função duas vezes com nomes diferentes.'),
  ('projetos.mao_obra.legado.descricao', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 8, 'Descrição', 'Opcional. O que essa função faz e que qualificação exige.', 'Referência para a equipe e para a proposta. Não entra no cálculo.', 'Monta estrutura e fecha forro e parede de drywall', 'Pôr aqui valores — eles têm campo próprio.'),
  ('projetos.mao_obra.legado.custo_hora', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 9, 'Custo / hora (R$)', 'Quanto custa uma hora deste profissional. Se deixar vazio, sai do custo mensal ÷ 220 h.', 'É multiplicado pelas horas da composição: horas × custo/hora = custo da mão de obra do serviço.', 'R$ 32,50', 'Lançar o salário mensal neste campo.'),
  ('projetos.mao_obra.legado.custo_mes', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 10, 'Custo / mês (R$)', 'O salário base ou o valor mensal contratado.', 'Quando o custo/hora está vazio, é a base dele (÷ 220 h).', 'R$ 2.800,00', 'Somar encargos aqui e de novo em Encargos (%) — conta em dobro.'),
  ('projetos.mao_obra.legado.encargos', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 11, 'Encargos (%)', 'O percentual de encargos sobre o custo. Referência: cerca de 80% para CLT, 0% para PJ.', 'Aumenta o custo da hora na composição: custo × (1 + encargos).', '80', 'Usar encargo de CLT para PJ ou empreitada.'),
  ('projetos.mao_obra.legado.status', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 12, 'Status', 'Ativo para usar em serviços novos; Inativo para tirar da escolha sem apagar.', 'Inativa não aparece para novos serviços; os serviços que já usam continuam com ela.', 'Inativo para uma função que a empresa não tem mais', 'Inativar achando que muda o custo dos serviços antigos.'),
  ('projetos.mao_obra.legado.observacoes', '/dashboard/projetos/mao-obra', 'Lista de mão de obra', 'hub_projetos', 13, 'Observações', 'Opcional. Nota interna sobre a função.', 'Só consulta. Não entra no cálculo nem na proposta.', 'Valor da convenção coletiva 2026', 'Guardar aqui informação que tem campo próprio.'),
  ('projetos.catalogo.bom.quantidade', '/dashboard/projetos/catalogo/[id]', 'Composição do serviço', 'hub_projetos', 1, 'Quantidade', 'Quanto deste item é usado para fazer UMA unidade do serviço (na unidade do item). Enter ou sair do campo salva.', 'Quantidade × custo unitário = custo do item no serviço; a soma dos itens forma o custo do serviço.', '0,35 placa por m² de forro', 'Lançar a quantidade da obra inteira em vez da quantidade por unidade.'),
  ('projetos.catalogo.bom.perda', '/dashboard/projetos/catalogo/[id]', 'Composição do serviço', 'hub_projetos', 2, 'Perda %', 'O percentual de sobra/quebra esperado deste item. Enter ou sair do campo salva.', 'Aumenta a quantidade considerada: quantidade × (1 + perda) antes de multiplicar pelo custo.', '10 (recortes de placa)', 'Somar a perda na quantidade E aqui — conta duas vezes.'),
  ('projetos.catalogo.seletor.busca', '/dashboard/projetos/catalogo/[id]', 'Composição do serviço', 'hub_projetos', 3, 'Buscar item', 'Digite parte do nome do material, da função ou do equipamento na aba escolhida.', 'Só filtra a lista para escolher o item que entra na composição.', 'placa', 'Buscar na aba errada (ex.: um material na aba Mão de Obra).'),
  ('projetos.precificacao.escopo', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 1, 'Escopo', 'Empresa toda ou uma linha de negócio. Escolha a linha para dar a ela premissas próprias.', 'As premissas da linha valem para os serviços dela; sem premissas próprias, vale a da empresa toda.', 'Linha "Forros e divisórias"', 'Editar a empresa toda achando que mudou só uma linha.'),
  ('projetos.precificacao.creditos_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 2, 'Créditos (%)', 'O percentual de imposto que você recupera na compra do material (crédito).', 'Reduz o custo do material antes de calcular impostos e margem: custo × (1 − créditos).', '9,25', 'Usar crédito sem ter direito a ele no seu regime — o preço sai baixo demais.'),
  ('projetos.precificacao.icms_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 3, 'ICMS (%)', 'A alíquota de ICMS sobre o material vendido.', 'Somado ao PIS/COFINS, forma o imposto do material: (custo − créditos) × (ICMS + PIS/COFINS).', '18', 'Lançar ICMS em serviço puro de mão de obra (lá é ISS).'),
  ('projetos.precificacao.pis_cofins_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 4, 'PIS/COFINS (%)', 'A alíquota somada de PIS e COFINS do seu regime.', 'Entra no imposto do material junto com o ICMS.', '3,65 (presumido) ou 9,25 (real)', 'Usar a alíquota de outro regime tributário.'),
  ('projetos.precificacao.margem_material_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 5, 'Margem Material (%)', 'O percentual que você quer ganhar sobre o material.', 'Aplicado sobre (custo + impostos) do material para chegar ao preço dele.', '25', 'Confundir margem com markup e somar os dois.'),
  ('projetos.precificacao.custo_folha_hora', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 6, 'Custo Folha/Hora (R$)', 'O custo médio de uma hora da sua equipe, com encargos.', 'Junto com o tempo por m², dá o custo de mão de obra por m²: custo/hora × tempo.', 'R$ 42,00', 'Usar só o salário, sem encargos — a mão de obra fica barata demais.'),
  ('projetos.precificacao.tempo_m2_min', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 7, 'Tempo por m² (min)', 'Quantos minutos a equipe leva, em média, para executar 1 m².', 'Multiplica o custo/hora para chegar ao custo de mão de obra por m².', '45', 'Lançar em horas (0,75) num campo de minutos.'),
  ('projetos.precificacao.imposto_mo_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 8, 'Imposto MO (%)', 'O percentual de imposto sobre a mão de obra (ISS e afins).', 'Somado ao custo da mão de obra antes da margem.', '5', 'Repetir aqui o ICMS do material.'),
  ('projetos.precificacao.margem_mo_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 9, 'Margem MO (%)', 'O percentual que você quer ganhar sobre a mão de obra.', 'Aplicado sobre (custo + imposto) da mão de obra.', '30', 'Pôr a mesma margem do material sem pensar no risco da execução.'),
  ('projetos.precificacao.comissao_pct', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 10, 'Comissão (%)', 'O percentual pago ao vendedor/parceiro sobre a venda.', 'Entra no preço final como custo comercial.', '3', 'Esquecer a comissão — ela sai da sua margem.'),
  ('projetos.precificacao.meta_producao_m2', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 11, 'Meta Produção (m²/mês)', 'Quantos m² a empresa planeja executar por mês.', 'Quando a base é Meta, divide o custo fixo mensal para achar o custo fixo por m².', '1.500', 'Meta irreal (alta demais) — o custo fixo por m² fica baixo e o preço não cobre a estrutura.'),
  ('projetos.precificacao.custo_fixo_m2', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 12, 'Custo Fixo (R$/m²) — digitado', 'O custo fixo por m² que você quer usar, digitado à mão.', 'É somado ao custo de cada m² quando a origem é manual.', 'R$ 12,00', 'Digitar aqui e também ligar o rateio — vale o que aparece em "Custo fixo por m² em uso".'),
  ('projetos.precificacao.custo_fixo_mensal', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 13, 'Custo Fixo Mensal (R$)', 'O total de custos fixos da empresa num mês (aluguel, administrativo, veículos).', 'Base do rateio: custo fixo mensal ÷ produção (meta ou realizada) = custo fixo por m².', 'R$ 18.000,00', 'Incluir aqui custos que já estão nos serviços (material, mão de obra direta).'),
  ('projetos.precificacao.realizado_producao_m2', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 14, 'Produção realizada (m²/mês)', 'Quantos m² a empresa de fato executou por mês, em média.', 'Quando a base é Realizado, divide o custo fixo mensal.', '1.200', 'Usar o mês de pico em vez da média.'),
  ('projetos.precificacao.base_custo_fixo', '/dashboard/projetos/configuracoes', 'Premissas de precificação', 'hub_projetos', 15, 'Base do custo fixo', 'Meta ou Realizado: qual produção divide o custo fixo mensal.', 'Define o divisor do rateio: Meta usa a produção planejada; Realizado, a executada.', 'Realizado, para preço mais seguro', 'Usar Meta otimista — o preço não cobre o fixo.'),
  ('projetos.produtividade.filtro_linha', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 1, 'Filtrar por linha', 'Escolha uma linha de negócio para ver só os produtos dela.', 'Só filtra a lista. Não muda valores.', 'Forros', 'Esquecer o filtro ligado e achar que o produto sumiu.'),
  ('projetos.produtividade.filtro_categoria', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 2, 'Filtrar por categoria', 'Escolha uma categoria para ver só esses produtos.', 'Só filtra a lista.', 'Drywall', 'Esquecer o filtro ligado.'),
  ('projetos.produtividade.novo_nome', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 3, 'Nome do produto', 'O nome do serviço/produto novo. É obrigatório.', 'É como ele aparece no catálogo, no orçamento e na proposta.', 'Forro de gesso acartonado', 'Nome genérico que ninguém acha na busca.'),
  ('projetos.produtividade.novo_unidade', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 4, 'Unidade', 'A unidade em que o produto é medido e vendido.', 'Base da produtividade (unidade por dia) e do custo por unidade.', 'm2', 'Cadastrar em m e orçar em m².'),
  ('projetos.produtividade.novo_categoria', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 5, 'Categoria', 'Opcional. O grupo do produto.', 'Filtra a lista e organiza o orçamento.', 'Forros', 'Criar categorias quase iguais.'),
  ('projetos.produtividade.novo_linha', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 6, 'Linha', 'A linha de negócio do produto.', 'Define que premissas de precificação valem para ele (as da linha ou as da empresa).', 'Forros e divisórias', 'Deixar sem linha e ele usar as premissas gerais.'),
  ('projetos.produtividade.novo_produtividade', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 7, 'Produtividade por dia', 'Quantas unidades a equipe executa num dia.', 'Define o prazo: quantidade ÷ produtividade = dias de equipe no cronograma.', '40 (m² por dia)', 'Informar a produtividade de uma pessoa quando a equipe tem duas.'),
  ('projetos.produtividade.novo_equipe', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 8, 'Equipe', 'Quem compõe a equipe que atinge essa produtividade.', 'Referência para o planejamento da obra. Não entra no preço.', '1 gesseiro + 1 ajudante', 'Não bater a equipe com a produtividade informada.'),
  ('projetos.produtividade.nome', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 9, 'Produto', 'O nome do produto. Edite e clique em Salvar na linha.', 'Muda como ele aparece no catálogo e nos orçamentos novos.', 'Forro de gesso acartonado', 'Esquecer de clicar em Salvar.'),
  ('projetos.produtividade.linha', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 10, 'Linha de negócio', 'A linha a que o produto pertence.', 'Define que premissas de precificação valem para ele.', 'Forros e divisórias', 'Trocar a linha sem conferir as premissas dela.'),
  ('projetos.produtividade.produtividade', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 11, 'Produtividade', 'Unidades executadas por dia pela equipe.', 'Usada no prazo e no cronograma da obra.', '40', 'Lançar por hora num campo por dia.'),
  ('projetos.produtividade.equipe', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 12, 'Equipe', 'Quem compõe a equipe.', 'Referência para planejamento. Não entra no preço.', '1 gesseiro + 1 ajudante', 'Deixar desatualizada depois de mudar a produtividade.'),
  ('projetos.produtividade.mo', '/dashboard/projetos/configuracoes', 'Produtos e produtividade', 'hub_projetos', 13, 'MO (R$/m²)', 'Só leitura. Para mudar, abra "Detalhar MO".', 'Soma de horas × custo/hora da mão de obra da composição do serviço.', 'R$ 18,40/m²', 'Procurar editar aqui — a edição é na ficha do serviço.'),
  ('projetos.bdi.administracao_central', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 1, 'Administração Central (AC)', 'O percentual de custos da estrutura administrativa rateado sobre a obra.', 'Compõe o BDI, que multiplica o custo direto para formar o preço.', '4', 'Somar aqui o custo fixo que já está nas premissas de precificação.'),
  ('projetos.bdi.seguros', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 2, 'Seguros (SG)', 'O percentual de seguros da obra: garantia, obras civis, responsabilidade civil.', 'Compõe o BDI.', '0,8', 'Esquecer quando o contrato exige seguro garantia.'),
  ('projetos.bdi.riscos', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 3, 'Riscos (RI)', 'A provisão para imprevistos e retrabalho.', 'Compõe o BDI.', '1,3', 'Zerar em obra com projeto incompleto.'),
  ('projetos.bdi.garantia', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 4, 'Garantias (GA)', 'O percentual para garantia técnica (NBR 15575) e retenção contratual.', 'Compõe o BDI.', '1', 'Ignorar a retenção prevista no contrato.'),
  ('projetos.bdi.despesas_financeiras', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 5, 'Despesas Financeiras (DF)', 'O custo do capital de giro durante a execução.', 'Compõe o BDI.', '1,2', 'Zerar quando o cliente paga por medição longa.'),
  ('projetos.bdi.lucro', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 6, 'Lucro (LU)', 'A margem de lucro líquido desejada.', 'Compõe o BDI; é o que sobra depois de todos os custos.', '8', 'Confundir com margem bruta.'),
  ('projetos.bdi.impostos', '/dashboard/projetos/configuracoes', 'BDI', 'hub_projetos', 7, 'Impostos (IM)', 'ISS + PIS + COFINS sobre o faturamento, conforme o seu regime.', 'Compõe o BDI, no denominador da fórmula (o imposto incide sobre o preço).', '8,65', 'Usar a alíquota de outro regime tributário.')
